        aFoldValue |= static_cast<std::uint32_t>(aSourceLaneC[aIndexC]) << 16U;
        aFoldValue |= static_cast<std::uint32_t>(aSourceLaneD[aIndexD]) << 0U;
        aFoldValue = TwistMix32::DiffuseA(aFoldValue);
